	vIsPerspective = float( isPerspectiveMatrix( projectionMatrix ) );
#endif
#if 0 > 0
	vClipPosition = - mvPosition.xyz;
#endif
#if defined( USE_ENVMAP ) || defined( DISTANCE ) || defined ( USE_SHADOWMAP ) || defined ( USE_TRANSMISSION ) || 0 > 0
