  float va = dot(ambHash(i), f);
  float vb = dot(ambHash(i + vec2(1.0, 0.0)), f - vec2(1.0, 0.0));
  float vc = dot(ambHash(i + vec2(0.0, 1.0)), f - vec2(0.0, 1.0));
  float vd = dot(ambHash(i + vec2(1.0, 1.0)), f - vec2(1.0, 1.0));

